function longestUnique(s) {
  const last = new Map()
  let left = 0
  let best = 0
  for (let right = 0; right <= s.length - 1; right++) {
    const ch = s[right]
    if (last.has(ch) && last.get(ch) >= left) {
      left = last.get(ch) + 1
    }
    last.set(ch, right)
    const len = right - left + 1
    if (len > best) best = len
  }
  return best
}

